NAME = 'GerZurcher: Deutsche Zürcher Bibel von 1931.'
BOOK = 'Ezra'

CHAPTERS = {
    1: {
        1: 'IM ersten Jahre des Königs Cyrus von Persien erweckte der Herr, um das Wort zu erfüllen, das er durch Jeremia geredet hatte, den Geist des Cyrus, des Königs von Persien, sodass er überall in seinem ganzen Königreich mündlich und auch schriftlich verkünden liess: (a) 2Ch 36:22 23; Jer 29:10',
        2: 'So spricht Cyrus, der König von Persien: Alle Königreiche der Erde hat mir der Herr, der Gott des Himmels, gegeben, und er selber hat mir aufgetragen, ihm zu Jerusalem in Juda ein Haus zu bauen.',
        3: 'Wer immer unter euch zu seinem Volke gehört, mit dem sei sein Gott, und er ziehe hinauf nach Jerusalem in Juda und baue das Haus des Herrn, des Gottes Israels. Das ist der Gott, der zu Jerusalem wohnt.',
        4: 'Und wer noch übrig ist, den sollen allerorten, wo er als Fremdling weilt, die Leute seines Ortes unterstützen mit Silber und Gold, mit Pferden und Vieh sowie mit freiwilligen Gaben für das Haus des Herrn in Jerusalem.',
        5: 'Da machten sich die Familienhäupter von Juda und Benjamin und die Priester und Leviten auf, kurz alle, deren Geist Gott erweckte, hinaufzuziehen, um das Haus des Herrn in Jerusalem zu bauen.',
        6: 'Und alle, die um sie her wohnten, unterstützten sie mit allem möglichen, mit Silber und Gold, mit Pferden und Vieh und Kostbarkeiten in Menge, ausser all den freiwilligen Gaben.',
        7: 'Und der König Cyrus liess die Tempelgeräte hervorholen, die Nebukadnezar aus Jerusalem weggeführt und in den Tempel seines Gottes getan hatte. (a) 2Ch 36:7 18',
        8: 'Cyrus, der König von Persien, liess sie hervorholen und übergab sie der Obhut des Schatzmeisters Mithredat, und dieser zählte sie Sesbazzar, dem Fürsten Judas, dar.',
        9: 'Und dies ist ihre Zahl: dreissig goldene Becken, 2 029 silberne Becken,',
        10: 'dreissig goldene Becher, 2 410 silberne Becher und tausend andre Geräte,',
        11: 'im ganzen an goldenen und silbernen Geräten 5 400. Dies alles brachte Sesbazzar mit herauf, als die Verbannten von Babel nach Jerusalem heraufgeführt wurden.',
    },
    2: {
        1: 'FOLGENDES sind die Bewohner der Provinz (Juda), die aus der Gefangenschaft heraufzogen von den Verbannten, die Nebukadnezar, der König von Babel, in die Verbannung nach Babel geführt hatte und die nun nach Jerusalem und Juda zurückkehrten, ein jeder in seine Stadt,',
        2: 'und zwar kamen sie mit Serubbabel, Jesua, Nehemia, Seraja, Reelaja, Nahamani, Mardochai, Bilsan, Mispar, Bigwai, Rehum und Baana. Zahl der Männer des Volkes Israel:',
        3: 'das Geschlecht Parhos: 2 172;',
        4: 'das Geschlecht Sephatja: 372;',
        5: 'das Geschlecht Arah: 775;',
        6: 'das Geschlecht Pahath-Moab, das heisst die Familien Jesua und Joab: 2 812;',
        7: 'das Geschlecht Elam: 1 254;',
        8: 'das Geschlecht Satthu: 945;',
        9: 'das Geschlecht Sakkai: 760;',
        10: 'das Geschlecht Bani: 642;',
        11: 'das Geschlecht Bebai: 623;',
        12: 'das Geschlecht Asgad: 1 222;',
        13: 'das Geschlecht Adonikam: 666;',
        14: 'das Geschlecht Bigwai: 2 056;',
        15: 'das Geschlecht Adin: 454;',
        16: 'das Geschlecht Ater, das heisst die Familie Hiskia: 98;',
        17: 'das Geschlecht Bezai: 323;',
        18: 'das Geschlecht Jora: 112;',
        19: 'das Geschlecht Hasum: 223;',
        20: 'die Männer von Gibeon: 95;',
        21: 'die Männer von Bethlehem: 123;',
        22: 'die Männer von Netopha: 56;',
        23: 'die Männer von Anathoth: 128;',
        24: 'die Männer von Beth-Asmaweth: 42;',
        25: 'die Männer von Kirjath-Jearim, Kephira und Beeroth: 743;',
        26: 'die Männer von Rama und Geba: 621;',
        27: 'die Männer von Michmas: 122;',
        28: 'die Männer von Bethel und Ai: 223;',
        29: 'die Männer von Nebo: 52;',
        30: 'das Geschlecht Magbis: 156;',
        31: 'das Geschlecht eines andern Elam: 1 254;',
        32: 'das Geschlecht Harim: 320;',
        33: 'die Männer von Lod, Hadid und Ono: 725;',
        34: 'die Männer von Jericho: 345;',
        35: 'das Geschlecht Senaa: 3 630.',
        36: 'Die Priester: das Geschlecht Jedaja, das heisst die Familie Jesua: 973;',
        37: 'das Geschlecht Immer: 1 052;',
        38: 'das Geschlecht Pashur: 1 247;',
        39: 'das Geschlecht Harim: 1 017.',
        40: 'Die Leviten: die Geschlechter Jesua, Kadmiel, Binnui und Hodawja: 74.',
        41: 'Die Sänger: das Geschlecht Asaph: 128.',
        42: 'Die Torhüter: das Geschlecht Sallum, das Geschlecht Ater, das Geschlecht Talmon, das Geschlecht Akkub, das Geschlecht Hatita und das Geschlecht Sobai: zusammen 139.',
        43: 'Die Tempelhörigen: das Geschlecht Ziha, das Geschlecht Hasupha, das Geschlecht Tabbaoth, (a) 1Ch 9:2',
        44: 'das Geschlecht Keros, das Geschlecht Siaha, das Geschlecht Padon,',
        45: 'das Geschlecht Lebana, das Geschlecht Hagaba, das Geschlecht Akkub,',
        46: 'das Geschlecht Hagab, das Geschlecht Salmai, das Geschlecht Hanan,',
        47: 'das Geschlecht Giddel, das Geschlecht Gahar, das Geschlecht Reaja,',
        48: 'das Geschlecht Rezin, das Geschlecht Nekoda, das Geschlecht Gassam,',
        49: 'das Geschlecht Ussa, das Geschlecht Paseah, das Geschlecht Besai,',
        50: 'das Geschlecht Asna, das Geschlecht Mehunim, das Geschlecht Nephisim,',
        51: 'das Geschlecht Bakbuk, das Geschlecht Hakupha, das Geschlecht Harhur,',
        52: 'das Geschlecht Bazluth, das Geschlecht Mehida, das Geschlecht Harsa,',
        53: 'das Geschlecht Barkos, das Geschlecht Sisera, das Geschlecht Themah,',
        54: 'das Geschlecht Neziah, das Geschlecht Hatipha.',
        55: 'Die Nachkommen der Sklaven Salomos: das Geschlecht Sotai, das Geschlecht Sophereth, das Geschlecht Peruda,',
        56: 'das Geschlecht Jaala, das Geschlecht Darkon, das Geschlecht Giddel,',
        57: 'das Geschlecht Sephatja, das Geschlecht Hattil, das Geschlecht Pochereth-Zebajim, das Geschlecht Amon,',
        58: 'alle Tempelhörigen und Nachkommen der Sklaven Salomos: 392.',
        59: 'Und die Folgenden sind diejenigen, die aus Thel-Melah, Thel-Harsa, Kerub-Addan und Immer mit heraufzogen, ohne angeben zu können, ob sie nach Familie und Herkunft aus Israel stammten:',
        60: 'das Geschlecht Delaja, das Geschlecht Tobia und das Geschlecht Nekoda: 652;',
        61: 'und von den Priestergeschlechtern: das Geschlecht Habaja, das Geschlecht Hakkoz und das Geschlecht jenes Barsillai, der eine von den Töchtern des Gileaditers Barsillai geheiratet hatte und nach dessen Namen genannt worden war. (a) 2Sa 17:27; 19:32-41',
        62: 'Diese hatten ihre Urkunde, das Geschlechtsregister, gesucht, doch es war nicht zu finden gewesen; darum wurden sie als unrein vom Priestertum ausgeschlossen,',
        63: 'und der Statthalter verbot ihnen, vom Heiligen zu essen, bis wieder ein Priester für die (Befragung der) Urim und Thummim erstünde. (a) 2Mo 28:30',
        64: 'Die ganze Gemeinde zählte insgesamt 42 360 Seelen,',
        65: 'abgesehen von ihren Sklaven und Sklavinnen; diese zählten 7 337 Seelen; und sie hatten zweihundert Sänger und Sängerinnen.',
        66: 'Ihrer Pferde waren 736 und ihrer Maultiere 245,',
        67: 'ihrer Kamele 435 und ihrer Esel 6 720.',
        68: 'Und etliche der Familienhäupter spendeten, als sie zum Tempel des Herrn in Jerusalem kamen, freiwillige Gaben für das Gotteshaus, damit man es an seiner (frühern) Stätte wieder aufbauen könne;',
        69: 'sie gaben nach ihrem Vermögen an den Schatz für den Gottesdienst 61 000 Drachmen in Gold, fünftausend Minen Silber und hundert Priestergewänder.',
        70: 'Und die Priester und Leviten und ein Teil des Volkes sowie die Sänger, Torhüter und Tempelhörigen liessen sich in den für sie bestimmten Ortschaften nieder, alle (übrigen) Israeliten aber in ihren Ortschaften.',
    },
    3: {
        1: 'ALS nun der siebente Monat herangekommen war - die Israeliten waren bereits in ihren Ortschaften -, kam das Volk einmütig in Jerusalem zusammen.',
        2: 'Jesua aber, der Sohn Jozadaks, nebst seinen Brüdern, den Priestern, und Serubbabel, der Sohn Sealthiels, nebst seinen Brüdern, gingen daran, den Altar des Gottes Israels wieder aufzubauen, um Brandopfer darauf darzubringen, wie es im Gesetze Moses, des Gottesmannes, vorgeschrieben ist. (a) 2Mo 27:1; 5Mo 12:6; Hag 1:12 14; Sac 4:9 10',
        3: 'Und sie errichteten den Altar an seiner (frühern) Stätte - es war nämlich ein Teil der Landbevölkerung mit ihnen verfeindet - und brachten darauf dem Herrn Brandopfer dar, Brandopfer am Morgen und am Abend. (a) 4Mo 28:3',
        4: 'Und sie begingen das Laubhüttenfest, wie es vorgeschrieben ist, und brachten Tag für Tag Brandopfer dar in der gesetzlich vorgeschriebenen Zahl, an einem jeden Tag, was sich gebührte, (a) 3Mo 23:34-43',
        5: 'darnach auch das tägliche Brandopfer und dasjenige an den Neumonden und allen geheiligten Festtagen des Herrn und die freiwilligen Gaben, sooft jemand dem Herrn eine solche darbrachte.',
        6: 'Am ersten Tage des siebenten Monats fingen sie an, dem Herrn Brandopfer darzubringen, obwohl der Grund zum Tempel des Herrn noch nicht gelegt war.',
        7: 'Sie gaben aber den Steinmetzen und Zimmerleuten Geld und den Sidoniern und Tyriern Speise, Getränk und Öl, dass sie Zedernstämme vom Libanon nach dem Hafen von Joppe brächten, wie es ihnen von Cyrus, dem König von Persien, erlaubt worden war.',
        8: 'Und im zweiten Jahr nach ihrer Ankunft beim Gotteshause in Jerusalem, im zweiten Monat, machten sich Serubbabel, der Sohn Sealthiels, und Jesua, der Sohn Jozadaks, und alle ihre Brüder, die Priester und Leviten, und alle, die aus der Verbannung nach Jerusalem gekommen waren, ans Werk, und sie bestellten die Leviten von zwanzig Jahren und darüber, die Arbeiten am Tempel des Herrn zu beaufsichtigen.',
        9: 'Und Jesua samt seinen Söhnen und Brüdern, Kadmiel, Binnui und Hodawja traten einmütig ihren Dienst an, die Arbeiter am Gotteshause zu beaufsichtigen, das Geschlecht Henadad, ihre Söhne und Brüder, die Leviten. (a) Esr 2:40',
        10: 'Als nun die Bauleute den Grund zum Tempel des Herrn legten, traten die Priester in ihren Gewändern mit Trompeten und die Leviten vom Geschlechte Asaph mit Zimbeln auf, den Herrn zu loben nach der Anordnung Davids, des Königs von Israel. (a) 2Ch 23:18',
        11: 'Und sie hoben an, dem Herrn zu lobsingen und zu danken: "Denn er ist freundlich; ja, seine Güte währet ewig über Israel", und das ganze Volk brach in lauten Jubel aus, indem es den Herrn lobpries, dass der Grund zum Tempel gelegt war. (a) 2Ch 5:13; Ps 106:118',
        12: 'Viele aber von den Priestern und Leviten und Familienhäuptern, die Alten, die den frühern Tempel noch gesehen hatten, weinten laut, als nun zu diesem der Grund gelegt wurde; viele andre jedoch brachen vor Freude in lauten Jubel aus. (a) Hag 2:3',
        13: 'Man konnte das Freudengeschrei nicht von dem lauten Weinen des Volkes unterscheiden; denn die Leute jubelten laut, sodass es weithin zu hören war.',
    },
    4: {
        1: 'ALS aber die Widersacher Judas und Benjamins hörten, dass die aus der Verbannung Heimgekehrten dem Herrn, dem Gott Israels, einen Tempel bauten,',
        2: 'kamen sie zu Serubbabel und Jesua und den Familienhäuptern und sprachen zu ihnen: Wir wollen mit euch bauen; denn wir verehren euren Gott wie ihr, und wir opfern ihm seit der Zeit Esarhaddons, des Königs von Assyrien, der uns hier heraufgeführt hat. (a) 2Kön 17:24-28',
        3: 'Aber Serubbabel und Jesua und die übrigen Familienhäupter Israels antworteten ihnen: Es geht nicht an, dass ihr und wir zusammen unsrem Gott einen Tempel bauen, sondern wir allein wollen dem Herrn, dem Gott Israels, bauen, wie uns Cyrus, der König von Persien, geboten hat.',
        4: 'Da machte das Volk im Lande die Judäer mutlos und schreckte sie ab vom Bauen.',
        5: 'Und sie bestachen Minister (am königlichen Hof) wider sie, ihr Vorhaben zu vereiteln, solange Cyrus, der König von Persien, lebte, und bis zur Regierung des Königs Darius von Persien.',
        6: 'Unter der Regierung des Ahasveros aber, im Anfang seiner Regierung, schrieben sie eine Anklage wider die Bewohner Judas und Jerusalems. (1) d.i. Xerxes.',
        7: 'Und in den Tagen des Arthahsastha schrieben Bislam, Mithredath und Tabeel und alle seine Genossen an Arthahsastha, den König von Persien. Der Text des Schreibens war aramäisch geschrieben und mit Übersetzung versehen. (1) d.i. Artaxerxes. (2) Aramäisch - diese Notiz ist ein Hinweis darauf, dass der folgende Abschnitt (bis Esra 6,18.) nicht in hebr., sondern in aram. Sprache geschrieben ist.',
        8: 'Rehum, der Befehlshaber, und Simsai, der Schreiber, schrieben einen Brief wider Jerusalem an den König Arthahsastha, also lautend:',
        9: 'Rehum, der Befehlshaber, und Simsai, der Schreiber, und alle ihre Genossen, die persischen Richter und persischen Beamten, die Leute von Arak, von Babel und von Susa das heisst aus Elam',
        10: 'und die übrigen Völker, die der grosse und erlauchte Asnappar weggeführt und in den Städten Samariens und den übrigen Ländern westlich des (Euphrat-)Stromes angesiedelt hat, (1) d.i. Assurbanipal.',
        11: 'dieses ist die Abschrift des Briefes, den sie an ihn sandten: "An König Arthahsastha, deine Knechte, die Leute westlich des Stromes. Und nun',
        12: 'sei dem König kund, dass die Juden, die von dir heraufgezogen, zu uns nach Jerusalem gekommen sind. Sie bauen die aufrührerische und böse Stadt wieder auf, vollenden die Mauern und bessern die Fundamente aus.',
        13: 'So sei nun dem König kund, dass, wenn die Stadt wieder aufgebaut wird und die Mauern vollendet werden, sie keinen Tribut, keine Abgaben und Zölle mehr entrichten und so das Einkommen der Könige schädigen werden.',
        14: 'Weil wir nun das Salz des Palastes gegessen haben und es uns nicht geziemt, die Schädigung des Königs mitanzusehen, darum senden wir hin und tun es dem König zu wissen, (1) d.h. weil wir dem Königshofe verpflichtet sind.',
        15: 'damit man im Buche der Chronik deiner Väter nachforsche. Du wirst dann im Buche der Chronik finden und erfahren, dass jene Stadt aufrührerisch und den Königen und Provinzen schädlich gewesen ist und dass man von alters her Empörung in ihr anstiftet; darum ist sie auch zerstört worden.',
        16: 'Wir tun also dem König zu wissen, dass, wenn jene Stadt wieder aufgebaut wird und ihre Mauern vollendet werden, du an den Ländern westlich des (Euphrat-)Stromes keinen Anteil mehr haben wirst."',
        17: 'Der König sandte Bescheid: "An Rehum, den Befehlshaber, und Simsai, den Schreiber, und alle ihre Genossen, die in Samarien und den übrigen Ländern westlich des (Euphrat-)Stromes wohnen, einen Gruss! Und nun,',
        18: 'das Schreiben, das ihr an uns gesandt habt, ist mir Wort für Wort vorgelesen worden,',
        19: 'und ich habe Befehl gegeben, nachzuforschen; da hat man gefunden, dass jene Stadt sich von alters her immer wieder gegen die Könige aufgelehnt hat und Aufruhr und Empörung in ihr angestiftet worden sind.',
        20: 'Mächtige Könige haben über Jerusalem regiert und über alle Länder westlich des (Euphrat-)Stromes geherrscht, und Tribut, Abgaben und Zölle wurden ihnen entrichtet.',
        21: 'So gebet nun Befehl, dass man jenen Männern Einhalt tue und dass jene Stadt nicht aufgebaut werde, bis der Befehl von mir gegeben wird.',
        22: 'Sehet zu, dass ihr hierin nicht lässig seid, damit nicht der Schaden gross werde zum Nachteil der Könige."',
        23: 'Als sodann die Abschrift des Schreibens des Königs Arthahsastha vor Rehum und Simsai, dem Schreiber, und ihren Genossen verlesen worden war, gingen sie eilends nach Jerusalem zu den Juden und zwangen sie mit Gewalt, (von ihrer Arbeit) abzustehen.',
        24: 'Darauf wurde die Arbeit am Gotteshause zu Jerusalem eingestellt und stand stille bis in das zweite Jahr der Regierung des Königs Darius von Persien.',
    },
    5: {
        1: 'HAGGAI aber und Sacharja, der Sohn Iddos, die Propheten, weissagten den Juden in Juda und Jerusalem im Namen des Gottes Israels, dem sie zu eigen gehörten. (a) Hag 1:1; Sac 1:1',
        2: 'Da machten sich Serubbabel, der Sohn Sealthiels, und Jesua, der Sohn Jozadaks, ans Werk und fingen an, das Gotteshaus zu Jerusalem zu bauen, und mit ihnen waren die Propheten Gottes, die sie unterstützten.',
        3: 'Zu derselben Zeit kamen zu ihnen Thatthenai, der Statthalter der Länder westlich des (Euphrat-)Stromes, und Sethar-Bosnai und ihre Genossen und sprachen zu ihnen also: "Wer hat euch befohlen, dieses Haus zu bauen und dieses Heiligtum zu vollenden,',
        4: 'und welches sind die Namen der Männer, die dieses Gebäude bauen?"',
        5: 'Aber das Auge ihres Gottes ruhte auf den Ältesten der Juden, sodass sie ihnen nicht Einhalt taten, bis der Bericht an Darius gelangt und dann das (königliche) Schreiben darüber zurückgekommen wäre.',
        6: 'Abschrift des Briefes, den Thatthenai, der Statthalter der Länder westlich des (Euphrat-)Stromes, und Sethar-Bosnai und seine Genossen, die Perser westlich des (Euphrat-)Stromes, an den König Darius sandten.',
        7: 'Sie sandten einen Bericht an ihn, und darin stand folgendes geschrieben: "Dem König Darius alles Heil!',
        8: 'Dem König sei kund, dass wir in die Provinz Juda gegangen sind zu dem Tempel des grossen Gottes. Es wurde eben daran gebaut mit grossen Quadern, und Balken wurden in die Wände eingesetzt; die Arbeit wurde genau ausgeführt und ging unter ihrer Hand tüchtig vonstatten.',
        9: "Da fragten wir jene Ältesten und sprachen also zu ihnen:,Wer hat euch befohlen, dieses Haus zu bauen und dieses Heiligtum zu vollenden?'",
        10: 'Auch nach ihren Namen fragten wir sie, um sie dir mitzuteilen; wir wollten nämlich die Namen der Männer aufschreiben, die an ihrer Spitze stehen.',
        11: 'Sie aber gaben uns folgendes zur Antwort:,Wir sind die Knechte des Gottes des Himmels und der Erde und bauen den Tempel wieder auf, der einst vor vielen Jahren hier stand und den ein grosser König Israels gebaut und vollendet hatte. (a) 1Kön 6:1 37 38',
        12: 'Weil jedoch unsre Väter den Gott des Himmels erzürnten, gab er sie in die Hand des Chaldäers Nebukadnezar, des Königs von Babel; der zerstörte diesen Tempel und führte das Volk nach Babel in die Verbannung. (a) 2Kön 24:10-16; 25:1-11',
        13: 'Aber im ersten Jahre seiner Regierung über Babel befahl König Cyrus, dieses Gotteshaus wieder aufzubauen. (a) Esr 1:1-3',
        14: 'Und auch die goldenen und silbernen Geräte des Gotteshauses, die Nebukadnezar aus dem Tempel zu Jerusalem weggenommen und in den Tempel zu Babel gebracht hatte, liess König Cyrus aus dem Tempel zu Babel wegnehmen, und sie wurden einem Manne mit Namen Sesbazzar übergeben, den er zum Statthalter eingesetzt hatte. (a) Esr 1:7 8',
        15: 'Und er sprach zu ihm: Nimm diese Geräte, ziehe hin und lege sie im Heiligtum zu Jerusalem nieder, und das Gotteshaus soll an seiner (frühern) Stätte wieder aufgebaut werden.',
        16: "Da kam jener Sesbazzar und legte die Fundamente zum Gotteshaus in Jerusalem; und seit der Zeit wird bis jetzt daran gebaut, aber es ist noch nicht fertig.'",
        17: 'Und nun, wenn es dem König gefällt, so forsche man nach in den Schatzhäusern des Königs dort in Babel, ob es sich so verhält, dass von König Cyrus befohlen worden ist, das Gotteshaus zu Jerusalem wieder aufzubauen, und der König wolle uns seine Entscheidung hierüber zukommen lassen."',
    },
    6: {
        1: 'Da befahl der König Darius, in den Schatzhäusern, in denen die Schriftstücke niedergelegt zu werden pflegten, nachzuforschen,',
        2: 'und man fand im Schloss zu Ahmeta, das in der Provinz Medien liegt, eine Schriftrolle; darin stand folgendes geschrieben: Protokoll: (1) d.i. Ekbatana.',
        3: '"Im ersten Jahre des Königs Cyrus befahl König Cyrus: Das Gotteshaus zu Jerusalem betreffend: Das Haus soll gebaut werden an der Stätte, wo man Schlachtopfer opfert und Feueropfer hinbringt; seine Höhe betrage sechzig Ellen und seine Breite sechzig Ellen.',
        4: 'Es sollen drei Schichten von grossen Quadern sein und eine Schicht von Holz, und die Kosten sollen aus der königlichen Kasse bezahlt werden.',
        5: 'Auch sollen die goldenen und silbernen Geräte des Gotteshauses, die Nebukadnezar aus dem Tempel zu Jerusalem weggenommen und nach Babel gebracht hat, zurückgegeben werden, und es soll (alles) wieder in den Tempel zu Jerusalem an seinen Ort kommen; und du sollst es im Gotteshause niederlegen."',
        6: 'Nun sollt ihr, Thatthenai, Statthalter der Länder westlich des (Euphrat-)Stromes, und SetharBosnai und eure Genossen, die Perser, die westlich des (Euphrat-)Stromes sind, euch von dort fernhalten;',
        7: 'lasset den Knecht Gottes Serubbabel, den Statthalter von Juda, und die Ältesten der Juden das Gotteshaus an seiner (frühern) Stätte bauen.',
        8: 'Auch ist von mir Befehl gegeben worden in betreff dessen, was ihr jenen Ältesten der Juden zu leisten habt, damit sie jenes Gotteshaus bauen können: aus des Königs Gütern, das heisst aus dem Tribut der Länder westlich des (Euphrat-)Stromes, sollen jenen Männern die Kosten pünktlich ausbezahlt werden, ungesäumt.',
        9: 'Und was sie bedürfen an jungen Stieren, Widdern und Lämmern zu Brandopfern für den Gott des Himmels sowie an Weizen, Salz, Wein und Öl, das soll ihnen nach der Weisung der Priester zu Jerusalem Tag für Tag genau, sodass nichts fehlt, gegeben werden,',
        10: 'damit sie dem Gott des Himmels duftende Opfer darbringen und für das Leben des Königs und seiner Söhne beten.',
        11: 'Und es ist von mir Befehl gegeben worden, dass, wenn irgend jemand diesen Erlass übertritt, man einen Balken aus seinem Hause reissen und ihn gepfählt daran heften soll, und sein Haus soll um deswillen zum Schutthaufen gemacht werden.',
        12: 'Der Gott aber, der seinen Namen dort hat wohnen lassen, stürze jeden König und jedes Volk, die es wagen sollten, dies zu übertreten, um jenes Gotteshaus in Jerusalem zu zerstören. Ich, Darius, habe den Befehl erlassen; er soll pünktlich ausgeführt werden.',
        13: 'Da taten Thatthenai, der Statthalter der Länder westlich des (Euphrat-)Stromes, und Sethar-Bosnai mit ihren Genossen genau so, wie ihnen der König Darius geschrieben hatte.',
        14: 'Und die Ältesten der Juden bauten weiter, und die Arbeit ging ihnen glücklich vonstatten durch die Weissagung der Propheten, nämlich Haggais und Sacharjas, des Sohnes Iddos, und sie führten (den Bau) zu Ende nach dem Befehl des Gottes Israels und nach dem Befehl des Cyrus und des Darius und des Königs Arthahsastha von Persien.',
        15: 'So wurden sie mit dem Hause fertig bis zum dritten Tage des Monats Adar, das heisst im sechsten Jahre der Regierung des Königs Darius.',
        16: 'Und die Israeliten, die Priester, die Leviten und die übrigen, die aus der Verbannung zurückgekehrt waren, feierten die Einweihung dieses Gotteshauses mit Freuden.',
        17: 'Und sie opferten zur Einweihung dieses Gotteshauses hundert Stiere, zweihundert Widder und vierhundert Lämmer, und als Sündopfer für ganz Israel zwölf Ziegenböcke nach der Zahl der Stämme Israels.',
        18: 'Auch bestellten sie die Priester nach ihren Abteilungen und die Leviten nach ihren Klassen zum Dienste des Gottes zu Jerusalem, wie es im Buche Moses vorgeschrieben ist. (a) 4Mo 3:6-10',
        19: 'Hierauf feierten die aus der Verbannung Zurückgekehrten das Passa am vierzehnten Tage des ersten Monats. (a) 2Mo 12:6',
        20: 'Denn die Priester und Leviten hatten sich insgesamt gereinigt, sie waren alle rein; und sie schlachteten das Passa für alle, die aus der Verbannung zurückgekehrt waren, und für ihre Stammesgenossen, die Priester, und für sich selbst.',
        21: 'Und es assen die Israeliten, die aus der Verbannung zurückgekehrt waren, sowie alle, die sich von der Unreinigkeit der Heiden im Lande abgesondert und sich ihnen angeschlossen hatten, den Herrn, den Gott Israels, zu verehren.',
        22: 'Dann feierten sie das Fest der ungesäuerten Brote sieben Tage lang mit Freuden; denn der Herr hatte ihnen Freude geschenkt und ihnen das Herz des Königs von Assyrien zugewendet, sodass er sie in der Arbeit am Tempel des Gottes Israels kräftig unterstützte.',
    },
    7: {
        1: 'NACH diesen Begebenheiten nun, unter der Regierung des Königs Arthahsastha von Persien, zog Esra, der Sohn Serajas, des Sohnes Asarjas, des Sohnes Hilkias,',
        2: 'des Sohnes Sallums, des Sohnes Zadoks, des Sohnes Ahitubs,',
        3: 'des Sohnes Amarjas, des Sohnes Asarjas, des Sohnes Merajoths,',
        4: 'des Sohnes Serahjas, des Sohnes Ussis, des Sohnes Bukkis,',
        5: 'des Sohnes Abisuas, des Sohnes des Pinehas, des Sohnes Eleasars, des Sohnes Aarons, des Hohenpriesters -',
        6: 'dieser Esra zog von Babel herauf. Er war ein Schriftgelehrter, wohlbewandert im Gesetz des Moses, das der Herr, der Gott Israels, gegeben hat. Und der König gewährte ihm alles, was er begehrte, da die Hand des Herrn, seines Gottes, über ihm war.',
        7: 'Und es zog (mit ihm) ein Teil der Israeliten, der Priester und der Leviten, der Sänger, der Torhüter und der Tempelhörigen im siebenten Jahre des Königs Arthahsastha nach Jerusalem herauf.',
        8: 'Und er kam im fünften Monat, und zwar im siebenten Jahre des Königs, in Jerusalem an.',
        9: 'Denn am ersten Tag des ersten Monats hatte er den Aufbruch von Babel angeordnet, und am ersten Tag des fünften Monats kam er nach Jerusalem, da die gütige Hand seines Gottes über ihm war.',
        10: 'Denn Esra war von ganzem Herzen bestrebt, das Gesetz des Herrn zu erforschen und zu befolgen und in Israel Satzung und Recht zu lehren.',
        11: 'Und dies ist der Wortlaut des Schreibens, das König Arthahsastha dem Priester Esra, dem Schriftgelehrten, gab, der wohlbewandert war in den Worten der Gebote und Satzungen des Herrn für Israel:',
        12: '"Arthahsastha, der König der Könige, an Esra, den Priester, der wohlbewandert ist im Gesetze des Himmelsgottes, und so weiter. Und nun,',
        13: 'es ist von mir Befehl gegeben worden, dass, wer in meinem Reiche vom Volke Israel und seinen Priestern und Leviten willens ist, nach Jerusalem zu ziehen, mit dir soll ziehen dürfen,',
        14: 'dieweil du ja vom König und seinen sieben Räten gesandt bist, eine Untersuchung anzustellen über die Verhältnisse in Juda und Jerusalem nach dem Gesetze deines Gottes, das du bei dir hast, (a) Es 1:14',
        15: 'und um das Silber und Gold hinzubringen, das der König und seine Räte für den Gott Israels, dessen Wohnung in Jerusalem ist, gespendet haben,',
        16: 'sowie alles Silber und Gold, das du in der ganzen Provinz Babel bekommen kannst, samt den freiwilligen Gaben, die das Volk und die Priester für den Tempel ihres Gottes zu Jerusalem spenden.',
        17: 'Deswegen sollst du gewissenhaft aus diesem Gelde Stiere, Widder und Lämmer nebst den dazugehörigen Speisopfern und Trankopfern kaufen und sie auf dem Altar beim Tempel eures Gottes zu Jerusalem opfern.',
        18: 'Und was dir und deinen Brüdern mit dem übrigen Silber und Gold zu tun gutdünkt, das mögt ihr nach dem Willen eures Gottes tun.',
        19: 'Und die Geräte, die dir für den Dienst im Tempel deines Gottes übergeben werden, sollst du vor dem Gott Israels in Jerusalem vollzählig abliefern;',
        20: 'die weitern Bedürfnisse des Tempels deines Gottes aber, für die zu sorgen dir obliegt, magst du aus dem königlichen Schatzhaus decken.',
        21: 'Ich, König Arthahsastha, befehle hiemit allen Schatzmeistern westlich des (Euphrat-)Stromes:,Alles, was der Priester Esra, der wohlbewandert ist im Gesetz des Himmelsgottes, von euch verlangt, soll pünktlich geleistet werden,',
        22: 'Silber bis auf hundert Talente und Weizen bis auf hundert Kor und Wein bis auf hundert Bath und Öl bis auf hundert Bath und beliebig viel Salz.',
        23: 'Alles, was dem Befehl des Himmelsgottes gemäss ist, das soll für den Tempel des Himmelsgottes gewissenhaft geleistet werden, damit nicht ein Zorngericht über das Reich des Königs und seiner Söhne komme.',
        24: "Ferner sei euch kund, dass man all den Priestern und Leviten, Sängern, Torhütern und Tempelhörigen, kurz den Dienern an diesem Gotteshause, keinerlei Tribut, Abgaben und Zölle auferlegen darf.'",
        25: 'Du aber, Esra, bestelle gemäss dem weisen Gesetze deines Gottes, das du bei dir hast, Richter und Rechtspfleger, die allem Volk westlich des (Euphrat-)Stromes Recht sprechen sollen, allen, die die Gesetze deines Gottes kennen; und wer sie nicht kennt, den sollt ihr sie lehren.',
        26: 'Und ein jeder, der das Gesetz deines Gottes und das Gesetz des Königs nicht befolgt, der soll genau (nach dem Gesetz) verurteilt werden, sei es zum Tode oder zur Verbannung, zu Geldbusse oder zu Gefängnis."',
        27: 'Gelobt sei der Herr, der Gott unsrer Väter, der dem König solches ins Herz gegeben hat, den Tempel des Herrn in Jerusalem zu verherrlichen,',
        28: 'und der mir die Gunst des Königs und seiner Räte und aller mächtigen Grossen des Königs zugewandt hat! So fasste ich denn Mut, da die Hand des Herrn, meines Gottes, über mir war, und versammelte Familienhäupter aus Israel, mit mir hinaufzuziehen.',
    },
    8: {
        1: 'Dies sind die Familienhäupter und die Geschlechtsregister derer, die mit mir unter der Regierung des Königs Arthahsastha von Babel heraufzogen:',
        2: 'vom Geschlechte Pinehas: Gersom; vom Geschlechte Ithamar: Daniel; vom Geschlechte David: Hattus,',
        3: 'der Sohn Sechanjas; vom Geschlechte Parhos: Sacharja, und mit ihm eingetragen 150 männliche Personen;',
        4: 'vom Geschlechte Pahath-Moab: Eljoenai, der Sohn Serahjas, und mit ihm zweihundert männliche Personen;',
        5: 'vom Geschlechte Satthu: Sechanja, der Sohn Jahasiels, und mit ihm dreihundert männliche Personen;',
        6: 'vom Geschlechte Adin: Ebed, der Sohn Jonathans, und mit ihm fünfzig männliche Personen;',
        7: 'vom Geschlechte Elam: Jesaja, der Sohn Athaljas, und mit ihm siebzig männliche Personen;',
        8: 'vom Geschlechte Sephatja: Sebadja, der Sohn Michaels, und mit ihm achtzig männliche Personen;',
        9: 'vom Geschlechte Joab: Obadja, der Sohn Jehiels, und mit ihm 218 männliche Personen;',
        10: 'vom Geschlechte Bani: Selomith, der Sohn Josiphjas, und mit ihm 160 männliche Personen;',
        11: 'vom Geschlechte Bebai: Sacharja, der Sohn Bebais, und mit ihm 28 männliche Personen:',
        12: 'vom Geschlechte Asgad: Johanan, der Sohn Hakkatans, und mit ihm 110 männliche Personen;',
        13: 'vom Geschlechte Adonikam: Spätere, die hiessen Eliphelet, Jegiel und Semaja, und mit ihnen sechzig männliche Personen;',
        14: 'und vom Geschlechte Bigwai: Uthai, der Sohn Sakkurs, und mit ihm siebzig männliche Personen.',
        15: 'Und ich versammelte sie an dem Fluss, der nach Ahawa fliesst, und wir lagerten dort drei Tage. Nun bemerkte ich zwar das Volk und die Priester, von den Leviten aber fand ich keinen dort.',
        16: 'Da sandte ich die Gemeindevorsteher Elieser, Ariel, Semaja, Elnathan, Jarib, Elnathan, Nathan, Sacharja und Mesullam und die Lehrer Jojarib und Elnathan',
        17: 'und gab ihnen Auftrag an Iddo, den Gemeindevorsteher in dem Ort Kasiphja, und legte ihnen die Worte in den Mund, die sie zu Iddo und seinen Brüdern in dem Ort Kasiphja reden sollten, dass sie uns Diener für das Haus unsres Gottes bringen möchten.',
        18: 'Und sie brachten uns, da die gütige Hand unsres Gottes über uns war, einen kundigen Mann aus dem Geschlechte Mahlis, des Sohnes Levis, des Sohnes Israels, Serebja samt seinen Söhnen und Brüdern, achtzehn Mann,',
        19: 'ferner Hasabja und mit ihm Jesaja vom Geschlechte Merari, samt ihren Brüdern und Söhnen, zwanzig Mann,',
        20: 'und von den Tempelhörigen, die David und die Fürsten für die Bedienung der Leviten als Hörige bestimmt hatten, 220 Mann; sie sind alle mit Namen ausdrücklich aufgezeichnet. (a) Jos 9:21 27; 1Ch 9:2',
        21: 'Dann liess ich daselbst am Ahawaflusse ein Fasten ausrufen, damit wir uns vor unserm Gott demütigten, um von ihm eine glückliche Reise für uns und unsre Familien und alle unsre Habe zu erbitten.',
        22: 'Denn ich hatte mich geschämt, den König um bewaffnete Leute und Reiter zu ersuchen, die uns auf dem Wege vor Feinden schützen würden; wir hatten vielmehr zum König gesagt: Die Hand unsres Gottes ist über allen, die ihn suchen, zu ihrem Besten, aber seine Macht und sein Zorn kommt über alle, die ihn verlassen.',
        23: 'Also fasteten wir und erflehten uns die Hilfe unsres Gottes in dieser Sache, und er liess sich erbitten.',
        24: 'Dann wählte ich aus den obersten Priestern zwölf Mann aus, ferner Serebja und Hasabja und mit ihnen zehn aus ihren Stammesgenossen,',
        25: 'und wog ihnen das Silber und das Gold und die Geräte dar, die Weihegabe für den Tempel unsres Gottes, die der König und seine Räte und Fürsten und alle Israeliten, die sich dort befanden, gespendet hatten,',
        26: 'und zwar übergab ich ihrer Obhut: an Silber 650 Talente, an silbernen Geräten hundert Talente und an Gold hundert Talente,',
        27: 'ferner zwanzig goldene Becher im Werte von tausend Dariken und zwölf kostbare Geräte von goldglänzendem Erz, köstlich wie Gold.',
        28: 'Und ich sprach zu ihnen: Ihr seid dem Herrn heilig, und die Geräte sind heilig; und das Silber und Gold ist eine Weihegabe für den Herrn, den Gott eurer Väter.',
        29: 'So seid nun wachsam und hütet es, bis ihr es vor den Obersten der Priester und Leviten und den Familienhäuptern Israels zu Jerusalem in den Zellen des Tempels darwägen könnt.',
        30: 'Da nahmen die Priester und Leviten das dargewogene Silber und Gold und die Geräte in Empfang, um sie nach Jerusalem in den Tempel unsres Gottes zu bringen.',
        31: 'Dann brachen wir am zwölften Tage des ersten Monats vom Ahawaflusse auf, um nach Jerusalem zu ziehen, und die Hand unsres Gottes war über uns, und er bewahrte uns vor Feinden und Wegelagerern.',
        32: 'So kamen wir nach Jerusalem und verweilten daselbst drei Tage lang.',
        33: 'Am vierten Tage aber wurden das Silber und das Gold und die Geräte im Tempel unsres Gottes gewogen und der Obhut des Priesters Meremoth, des Sohnes Urias, übergeben; mit ihm war auch Eleasar, der Sohn des Pinehas, zugegen, und ausser ihnen noch die Leviten Josabad, der Sohn Jesuas, und Noadja, der Sohn Binnuis.',
        34: 'Alles wurde nachgezählt und nachgewogen, und das ganze Gewicht wurde aufgeschrieben.',
        35: 'Damals brachten die Verbannten, die nun aus der Gefangenschaft heimgekehrt waren, dem Gott Israels Brandopfer dar: zwölf Stiere für ganz Israel, 96 Widder, 77 Lämmer, zwölf Böcke zum Sündopfer, alles als Brandopfer für den Herrn.',
        36: 'Dann übergaben sie die Befehle des Königs den Satrapen des Königs und den Statthaltern westlich des (Euphrat-)Stromes, und diese unterstützten das Volk und das Gotteshaus.',
    },
    9: {
        1: 'ALS nun das alles erledigt war, traten die Obersten zu mir und sprachen: Die Leute, sowohl (gewöhnliche) Israeliten als auch Priester und Leviten, halten sich nicht abgesondert von den Heidenvölkern, von ihren Greueln, von den Kanaanitern, Hethitern Pheresitern, Jebusitern, Ammonitern, Moabitern, Ägyptern und Amoritern;',
        2: 'denn sie haben von den Töchtern derselben Frauen für sich und ihre Söhne genommen, und so hat sich das heilige Geschlecht mit den Heidenvölkern vermischt, und die Obersten und Vorsteher sind in diesem Frevel vorangegangen. (a) 5Mo 7:3; Ne 13:23',
        3: 'Als ich solches hörte, zerriss ich mein Kleid und meinen Mantel und raufte mir das Haupthaar und den Bart und sass betäubt da.',
        4: 'Da versammelten sich bei mir alle, die die Worte des Gottes Israels fürchteten wegen des Frevels derer, die aus der Verbannung gekommen waren, während ich bis zum Abendopfer betäubt dasass.',
        5: 'Zur Zeit des Abendopfers aber stand ich auf von meiner Kasteiung, und indem ich mein Kleid und meinen Mantel zerriss, fiel ich auf die Kniee, breitete die Hände aus zu dem Herrn, meinem Gott,',
        6: 'und sprach: Mein Gott, ich bin zu beschämt, zu tief zerknirscht, als dass ich mein Angesicht zu dir, mein Gott, erheben dürfte; denn unsre Missetaten sind hoch über uns gestiegen, und unsre Schuld reicht bis zum Himmel.',
        7: 'Seit den Tagen unsrer Väter bis auf diesen Tag sind wir in grosser Schuld, und um unsrer Missetaten willen sind wir, unsre Könige und unsre Priester den Königen der Länder preisgegeben worden, dem Schwert, der Verbannung, der Plünderung und der Entehrung, wie es heute am Tage liegt.',
        8: 'Wohl ist uns jetzt für einen kurzen Augenblick von dem Herrn, unsrem Gott, Erbarmen widerfahren: er hat von uns einen Rest Geretteter am Leben erhalten und uns eine Rast geschenkt an seiner heiligen Stätte; unser Gott hat unsre Augen wieder hell gemacht und uns in unsrer Knechtschaft ein wenig aufleben lassen;',
        9: 'denn wir sind zwar Knechte, doch hat uns unser Gott in unsrer Knechtschaft nicht verlassen, sondern hat uns die Gunst der Könige von Persien zugewandt. Er hat uns wieder aufleben lassen, um das Haus unsres Gottes aufzurichten und seine Trümmer wiederherzustellen, und uns in Juda und Jerusalem eine schützende Mauer gegeben.',
        10: 'Nun aber, unser Gott, was sollen wir nach alledem sagen? Wir haben ja deine Gebote verlassen,',
        11: 'die du durch deine Knechte, die Propheten, gegeben hast, indem du sagtest: "Das Land, in das ihr einzieht, es in Besitz zu nehmen, ist ein beflecktes Land; die Heidenvölker haben es befleckt durch ihre Greuel, mit denen sie es vom einen Ende bis zum andern infolge ihrer Unreinheit erfüllt haben. (a) 3Mo 18:24 25',
        12: 'So sollt ihr nun eure Töchter nicht ihren Söhnen geben noch um ihre Töchter werben für eure Söhne. Nie sollt ihr auf ihre Wohlfahrt und ihr Glück bedacht sein, damit ihr stark werdet und die Güter des Landes geniesset und es für alle Zeiten auf eure Kinder vererbet." (a) 5Mo 23:6',
        13: 'Nach alledem nun, was über uns gekommen ist um unsrer bösen Taten und unsrer grossen Schuld willen - und doch hast du ja, unser Gott, mehr Schonung walten lassen, als wir nach unsrer Schuld verdient, und hast uns diesen Rest Geretteter geschenkt -',
        14: 'sollten wir da wiederum deine Gebote brechen und mit den Völkern, die solche Greuel treiben, uns verschwägern? Würdest du uns da nicht zürnen und uns ganz vernichten, sodass keiner mehr übrigbliebe und gerettet würde?',
        15: 'O Herr, Gott Israels, du bist gerecht darin, dass heute nur noch ein Rest Geretteter von uns am Leben ist. Siehe, wir stehen da vor deinem Angesicht in unsrer Schuld; bei solchem Tun kann niemand vor dir bestehen.',
    },
    10: {
        1: 'Während Esra also betete und unter Tränen vor dem Hause Gottes liegend sein Bekenntnis ablegte, versammelte sich bei ihm eine sehr grosse Gemeinde von Israeliten, Männer, Frauen und Kinder; denn das Volk weinte heftig.',
        2: 'Und Sechanja, der Sohn Jehiels, vom Geschlechte Elam, hob an und sprach zu Esra: Wir haben unsrem Gott die Treue gebrochen, indem wir fremde Frauen aus den Völkern im Lande heimgeführt haben. Und doch gibt es auch jetzt noch eine Hoffnung für Israel.',
        3: 'Lasst uns nun unsrem Gott geloben, alle unsre fremden Frauen und die von ihnen geboren sind, zu verstossen gemäss deinem Vorschlag, mein Herr, und dem Vorschlag derer, die das Gebot unsres Gottes fürchten, damit man nach dem Gesetz verfahre.',
        4: 'Steh auf! Dir liegt es ob. Wir stehen zu dir. Sei stark und handle!',
        5: 'Da stand Esra auf und liess die Obersten der Priester und der Leviten und von ganz Israel schwören, nach diesem Wort zu tun, und sie schwuren.',
        6: 'Dann verliess Esra den Ort vor dem Hause Gottes und ging in die Zelle Johanans, des Sohnes Eljasibs, und blieb dort die Nacht über, ohne zu essen und zu trinken; denn er trauerte über den Frevel der aus der Verbannung Heimgekehrten.',
        7: 'Darnach liessen sie in Juda und Jerusalem ausrufen, alle aus der Verbannung Heimgekehrten sollten sich in Jerusalem versammeln,',
        8: 'und wer nicht binnen drei Tagen gemäss dem Beschluss der Obersten und Ältesten erschiene, dessen ganze Habe sollte dem Bann verfallen und er selbst aus der Gemeinde der Heimgekehrten ausgeschlossen werden.',
        9: 'Da versammelten sich alle Männer Judas und Benjamins in Jerusalem binnen drei Tagen, das heisst am zwanzigsten Tage des neunten Monats, und das ganze Volk sass auf dem Platze vor dem Gotteshause, zitternd um der Angelegenheit willen und infolge des Regens.',
        10: 'Und Esra, der Priester, stand auf und sprach zu ihnen: Ihr habt euch versündigt; ihr habt fremde Frauen heimgeführt und damit die Schuld Israels noch grösser gemacht. (a) 5Mo 7:3',
        11: 'So legt nun dem Herrn, dem Gott eurer Väter, ein Bekenntnis ab und tut, was ihm wohlgefällig ist: scheidet euch von den Völkern im Lande und von den fremden Frauen!',
        12: 'Da antwortete die ganze Gemeinde und sprach mit lauter Stimme: Ja, es ist unsre Pflicht, zu tun, wie du gesagt hast.',
        13: 'Aber des Volkes ist viel, und es ist Regenzeit, sodass man nicht hier draussen stehen kann. Die Angelegenheit ist auch nicht in ein, zwei Tagen abzumachen; denn wir haben uns in dieser Sache viel zuschulden kommen lassen.',
        14: 'Unsre Obersten mögen für die ganze Gemeinde tagen; dann sollen alle die in unsern Städten, die fremde Frauen heimgeführt haben, zu bestimmten Zeiten kommen und mit ihnen die Ältesten und Richter einer jeden Stadt, bis wir den glühenden Zorn unsres Gottes, der um dieser Sache willen entbrannt ist, von uns abgewendet haben.',
        15: 'Nur Jonathan, der Sohn Asahels, und Jahseja, der Sohn Thikwas, traten dagegen auf, und Mesullam und der Levit Sabbethai unterstützten sie.',
        16: 'Aber die aus der Verbannung Heimgekehrten führten den Vorschlag aus, und der Priester Esra erwählte sich Männer, die Familienhäupter der einzelnen Familien, und zwar alle mit Nennung des Namens, und diese hielten am ersten Tage des zehnten Monats Sitzung, um die Sache zu untersuchen,',
        17: 'und sie erledigten die Angelegenheit mit all den Männern, die fremde Frauen heimgeführt hatten, bis zum ersten Tage des ersten Monats.',
        18: 'Und es wurden unter der Priesterschaft als solche, die fremde Frauen heimgeführt hatten, folgende gefunden: vom Geschlechte Jesuas, des Sohnes Jozadaks, und seiner Brüder: Maaseja, Elieser, Jarib und Gedalja;',
        19: 'die gaben ihre Hand darauf, dass sie ihre Frauen verstossen wollten, und ihr Schuldopfer war ein Widder für ihre Schuld.',
        20: 'Vom Geschlechte Immer: Hanani und Sebadja;',
        21: 'vom Geschlechte Harim: Maaseja, Elia, Semaja, Jehiel und Usia;',
        22: 'vom Geschlechte Pashur: Eljoenai, Maaseja, Ismael, Nethaneel, Josabad und Eleasa.',
        23: 'Unter den Leviten: Josabad, Simei, Kelaja sonst Kelita, Pethahja, Juda und Elieser;',
        24: 'unter den Sängern: Eljasib; unter den Torhütern: Sallum, Telem und Uri.',
        25: 'Unter den (gewöhnlichen) Israeliten: vom Geschlechte Parhos: Ramja, Jissia, Malchia, Mijamin, Eleasar, Hasabja und Benaja;',
        26: 'vom Geschlechte Elam: Matthanja, Sacharja, Jehiel, Abdi, Jeremoth und Elia;',
        27: 'vom Geschlechte Satthu: Eljoenai, Eljasib, Matthanja, Jeremoth, Sabad und Asisa;',
        28: 'vom Geschlechte Bebai: Johanan, Hananja, Sabbai und Athlai;',
        29: 'vom Geschlechte Bani: Mesullam, Malluch, Adaja, Jasub, Jiseal und Jeremoth;',
        30: 'vom Geschlechte Pahath-Moab: Adna, Chelal, Benaja, Maaseja, Matthanja, Bezaleel, Binnui und Manasse;',
        31: 'vom Geschlechte Harim: Elieser, Jissia, Malchia, Semaja, Simeon,',
        32: 'Benjamin, Malluch und Semarja;',
        33: 'vom Geschlechte Hasum: Matthenai, Matthattha, Sabad, Eliphelet, Jeremai, Manasse und Simei;',
        34: 'vom Geschlechte Bigwai: Maadai, Amram, Joel,',
        35: 'Benaja, Bedja und Cheluhu;',
        36: 'vom Geschlechte Meremoth: Eljasib,',
        37: 'Matthanja, Matthenai und Jaasai;',
        38: 'vom Geschlechte Binnui: Simei,',
        39: 'Selemja, Nathan und Adaja;',
        40: 'vom Geschlechte Assur: Sasai, Sarai,',
        41: 'Asareel, Selemja, Semarja,',
        42: 'Sallum, Amarja und Joseph;',
        43: 'und vom Geschlechte Nebo: Jegiel, Matthithja, Sabad, Sebina, Jaddai, Joel und Benaja.',
        44: 'Diese alle hatten fremde Frauen genommen, und sie entliessen Frauen und Kinder.',
    },
}
